-- Generated constraint fragment for the Action Owner migration; not a migration.
CONSTRAINT action_state_check CHECK (lifecycle IS NOT NULL AND outcome IS NOT NULL AND ((lifecycle = 'Proposed' AND outcome IN ('NotStarted')) OR (lifecycle = 'Validated' AND outcome IN ('NotStarted')) OR (lifecycle = 'Authorized' AND outcome IN ('NotStarted')) OR (lifecycle = 'Executing' AND outcome IN ('Pending', 'Unknown')) OR (lifecycle = 'Reconciling' AND outcome IN ('Pending', 'Unknown')) OR (lifecycle = 'Closed' AND outcome IN ('Succeeded', 'PartiallySucceeded', 'Failed')) OR (lifecycle = 'Rejected' AND outcome IN ('NotStarted')) OR (lifecycle = 'Expired' AND outcome IN ('NotStarted')) OR (lifecycle = 'Cancelled' AND outcome IN ('NotStarted'))))
